SELECT   ---DISTINCT        A.[DocDate] AS 'NGÀY CHỨNG TỪ',          -- [CHUYỂN ĐỔI: Gọi trực tiếp từ bảng E đã LEFT JOIN bên dưới]        ISNULL(E.[BPLName], N'Trụ sở chính') AS N'TÊN CHI NHÁNH',         -- ====================================================        -- Chuyển đổi DocTime thành định dạng HH:MM          --RIGHT('0' + LEFT(A.DocTime, LEN(A.DocTime) - 2), 2) + ':' + RIGHT(A.DocTime, 2) AS DocTime,          CASE              WHEN A.TransType = -2 THEN N'OB (NHẬP ĐẦU KỲ)'              WHEN A.TransType = 13 THEN N'AR Invoice (XUẤT BÁN)'              WHEN A.TransType = 14 THEN N'AR Credit Memo (NHẬN HÀNG BÁN TRẢ LẠI)'              WHEN A.TransType = 15 THEN N'Delivery (XUẤT KHO GIAO HÀNG)'              WHEN A.TransType = 16 THEN N'Delivery Return (NHẬN HÀNG TRẢ LẠI)'              WHEN A.TransType = 18 THEN N'AP Invoice (NHẬP MUA)'              WHEN A.TransType = 19 THEN N'AP Credit Memo (XUẤT TRẢ HÀNG MUA)'              WHEN A.TransType = 20 THEN N'GRPO (NHẬP KHO HÀNG MUA)'              WHEN A.TransType = 21 THEN N'Goods Return (XUẤT TRẢ HÀNG MUA)'              WHEN A.TransType = 59 AND ApplObj = 202 THEN 'Prdn Receipt'              WHEN A.TransType = 59 AND ApplObj <> 202 THEN N'Goods Receipt (NHẬP KHO THÀNH PHẨM)'              WHEN A.TransType = 60 AND ApplObj = 202 THEN N'Prdn Issue'              WHEN A.TransType = 60 AND ApplObj <> 202 THEN N'Goods Issue (XUẤT KHO NVL)'              WHEN A.TransType = 67 THEN N'Inventory Transfer (CHUYỂN KHO)'              WHEN A.TransType = 69 THEN N'Landed Cost (PHÍ HẢI QUAN)'              WHEN A.TransType = 162 THEN N'Inventory Valuation (ĐIỀU CHỈNH GIÁ VỐN)'              WHEN A.TransType = 202 THEN N'Production Order Closing'              ELSE N'KHÁC'          END AS N'LOẠI GIAO DỊCH',          A.Comments AS N'Diễn giải 1',        A.JrnlMemo AS N'Diễn giải 2',        A.BASE_REF AS N'SỐ CHỨNG TỪ TRÊN SAP',        --F.U_znr as N'ĐƠN HÀNG',        A.Ref2 as N'WO Num - Đơn Hàng',        A.ItemCode AS N'MÃ HÀNG',          B.ItemName AS N'TÊN HÀNG',          A.CardCode AS N'MÃ KHÁCH/NCC',          D.CardName AS N'TÊN KHÁCH/NCC',          A.InQty - A.OutQty AS N'SỐ LƯỢNG NHẬP/XUẤT',          A.Price AS N'ĐƠN GIÁ',        A.TransValue AS N'THÀNH TIỀN',          A.Warehouse AS N'KHO',          C.ItmsGrpNam AS N'NHÓM'           FROM           [OINM] A      INNER JOIN           [OITM] B ON A.[ItemCode] = B.[ItemCode]      INNER JOIN           [OITB] C ON B.[ItmsGrpCod] = C.[ItmsGrpCod]      LEFT OUTER JOIN           [OCRD] D ON A.[CardCode] = D.[CardCode]              -- [THÊM JOIN] Thay thế cho Subquery để tránh lỗi bộ phân tích cú pháp của SAP B1    LEFT OUTER JOIN         [OWHS] W ON A.[Warehouse] = W.[WhsCode]    LEFT OUTER JOIN         [OBPL] E ON W.[BPLid] = E.[BPLId]     --Mr Thien edit script JOIN TO WO WHEN MATERIAL ISSUES    --inner JOIN IGE1 E ON A.BASE_REF = E.DocEntry AND A.TransType = 60    --inner join BEAS_FTPOS F ON E.U_belnrid = F.BELNR_ID AND E.U_belposid = F.BELPOS_ID WHERE    A.[DocDate] >= /* A.DocDate */ '[%1]'  AND A.[DocDate] <= /* A.DocDate */ '[%2]'AND  A.[TransValue] <> 0